<?php $pdfQuery=http_build_query(array_filter(['search'=>$search,'class'=>$selectedClass],static fn($v)=>$v!==''&&$v!==0)); ?>
<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Admission Details</h1><p>Bounded persisted admission report.</p></div><div class="filter-actions"><a class="btn btn--primary" href="<?=e(url('/admin/reports/admissions/pdf'.($pdfQuery?'?'.$pdfQuery:'')))?>" target="_blank" rel="noopener"><i data-lucide="file-down"></i>Open PDF</a><a class="btn btn--secondary" href="<?=e(url('/admin/reports/admissions/pdf?'.($pdfQuery?$pdfQuery.'&':'').'download=1'))?>"><i data-lucide="download"></i>Download</a></div></header><form class="filter-bar filter-bar--compact"><input class="module-input" name="search" value="<?= e($search) ?>" placeholder="Name or registration"><select class="module-select" name="class"><option value="">All Classes</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>" <?= $selectedClass==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select><button class="btn btn--secondary">Filter</button></form><?php $st=array_count_values(array_map(static fn($x)=>(string)($x['status']??'active'),$rows));$newThisMonth=count(array_filter($rows,static fn($x)=>str_starts_with((string)($x['date_of_admission']??''),date('Y-m'))));?><div class="metric-grid"><div class="metric-card"><span>Students</span><strong><?=(int)$paginator->total?></strong></div><div class="metric-card"><span>Active</span><strong><?=(int)($st['active']??0)?></strong></div><div class="metric-card"><span>Inactive / Suspended</span><strong><?=(int)($st['inactive']??0)?> / <?=(int)($st['suspended']??0)?></strong></div><div class="metric-card"><span>Admitted this month</span><strong><?=(int)$newThisMonth?></strong></div></div><section class="module-card"><div class="module-card__body"><div class="table-scroll wide-report"><table class="data-table"><thead><tr><th>Sr</th><th>ID</th><th>Student Name</th><th>Father Name</th><th>Class</th><th>Discount</th><th>Admission Date</th><th>DOB</th><th>Age</th><th>Gender</th><th>NIC</th><th>Religion</th><th>Cast</th><th>Status</th></tr></thead><tbody><?php foreach($rows as$i=>$s):$age=$s['date_of_birth']?(new DateTimeImmutable($s['date_of_birth']))->diff(new DateTimeImmutable('today'))->y:null;?><tr><td><?= $paginator->offset()+$i+1 ?></td><td><?= e($s['registration_no']) ?></td><td><?= e($s['student_name']) ?></td><td><?= e($s['father_name']?:'—') ?></td><td><?= e($s['class_name']) ?></td><td><?= e($s['discount_in_fee']) ?>%</td><td><?= e($s['date_of_admission']) ?></td><td><?= e($s['date_of_birth']?:'—') ?></td><td><?= $age??'—' ?></td><td><?= e($s['gender']?:'—') ?></td><td><?= e($s['birth_form_nic']?:'—') ?></td><td><?= e($s['religion']?:'—') ?></td><td><?= e($s['caste']?:'—') ?></td><td><?= e($s['status']) ?></td></tr><?php endforeach ?></tbody></table></div><p><?= $paginator->total ?> records · Page <?= $paginator->currentPage ?> / <?= $paginator->lastPage() ?></p></div></section></div></div></main>
